        }
        i += 2; // skip the next two arguments
        continue;

metadata.output:
      if (dumpopts & JV_PRINT_COLOR) {
        jv_dump(result, dumpopts);
      } else if (result_kind == JV_KIND_NULL) {
        priv_fwrite("null", 4, stdout, tty_out);
        jv_free(result);
      } else if (result_kind == JV_KIND_FALSE) {
        priv_fwrite("false", 5, stdout, tty_out);
        jv_free(result);
      } else if (result_kind == JV_KIND_TRUE) {
        priv_fwrite("true", 4, stdout, tty_out);
        jv_free(result);
      } else {
        jv_dump(result, dumpopts);
      }
    }
    if (!(options & RAW_NO_LF))
      priv_fwrite("\n", 1, stdout, tty_out);
    if (options & RAW_NUL)
      priv_fwrite("\0", 1, stdout, tty_out);
    if (options & UNBUFFERED_OUTPUT)
      fflush(stdout);
  }
  if (jq_halted(jq)) {
    // jq program invoked `halt` or `halt_error`
    options |= EXIT_STATUS_EXACT;
    jv exit_code = jq_get_exit_code(jq);
    jv_kind exit_kind = jv_get_kind(exit_code);
    if (exit_kind == JV_KIND_INVALID)
      ret = JQ_OK;
    else if (exit_kind == JV_KIND_NUMBER)
      ret = jv_number_value(exit_code);
    else
      ret = JQ_ERROR_UNKNOWN;
    jv_free(exit_code);
    jv error_message = jq_get_error_message(jq);
    jv_kind error_kind = jv_get_kind(error_message);
    if (error_kind == JV_KIND_STRING) {
      fprintf(stderr, "jq: error: %s", jv_string_value(error_message));
    } else if (error_kind == JV_KIND_NULL) {
      // Halt with no output
    } else if (jv_is_valid(error_message)) {
      error_message = jv_dump_string(jv_copy(error_message), 0);
      fprintf(stderr, "jq: error: %s\n", jv_string_value(error_message));
    }
    fflush(stderr);
    jv_free(error_message);
  } else if (jv_invalid_has_msg(jv_copy(result))) {
    // Uncaught jq exception
    jv msg = jv_invalid_get_msg(jv_copy(result));
    jv filename = jq_util_input_get_current_filename(jq);
    jv line = jq_util_input_get_current_line(jq);
    jv input_pos;
    if (jv_get_kind(filename) == JV_KIND_STRING) {
      if (jv_get_kind(line) == JV_KIND_NUMBER) {
        input_pos = jv_string_fmt("%s:%lu",
                                  jv_string_value(filename),
                                  (unsigned long)jv_number_value(line));
      } else {
        input_pos = jq_util_input_get_position(jq);
      }
    } else {
      input_pos = jq_util_input_get_position(jq);
    }
    jv_free(filename);
    jv_free(line);
    if (jv_get_kind(msg) == JV_KIND_STRING) {
      fprintf(stderr, "jq: error (at %s): %s\n",
              jv_string_value(input_pos), jv_string_value(msg));
    } else {
      msg = jv_dump_string(msg, 0);
      fprintf(stderr, "jq: error (at %s) (not a string): %s\n",
              jv_string_value(input_pos), jv_string_value(msg));
    }
    ret = JQ_ERROR_UNKNOWN;
    jv_free(input_pos);
    jv_free(msg);
  }
  jv_free(result);
  return ret;
}

static void debug_cb(void *data, jv input) {
  int dumpopts = *(int *)data;
  jv_dumpf(JV_ARRAY(jv_string("DEBUG:"), input), stderr, dumpopts & ~(JV_PRINT_PRETTY));
  fprintf(stderr, "\n");
}

